const int micPin = A0;
const int ledPins[3] = {9, 10, 11};

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 3; i++) pinMode(ledPins[i], OUTPUT);
}

void loop() {
  int raw = analogRead(micPin);
  int amplitude = abs(raw - 512);

  digitalWrite(ledPins[0], amplitude > 20 ? HIGH : LOW);
  digitalWrite(ledPins[1], amplitude > 60 ? HIGH : LOW);
  digitalWrite(ledPins[2], amplitude > 120 ? HIGH : LOW);

  delay(20);
}
